import json
import sys

def run(q):
    if q.get("command") == "ping":
        return {"status": "ok", "product": "Courier Relay"}
    if q.get("command") == "count":
        receipts = q["receipts"]
        delivery_ids = {receipt["delivery_id"] for receipt in receipts}
